from __future__ import annotations

import heapq
from typing import List


class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        """
        Return the median of two sorted arrays in O(log(min(m, n))).

        Binary-search the partition point in the smaller array so that:
          - left half contains half the total elements
          - every element in left half <= every element in right half
        """
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        if m == 0:
            # Median of a single sorted array
            mid = n // 2
            if n % 2 == 1:
                return float(nums2[mid])
            return (nums2[mid - 1] + nums2[mid]) / 2.0

        half = (m + n + 1) // 2
        lo, hi = 0, m

        while lo <= hi:
            i = (lo + hi) // 2          # partition in nums1
            j = half - i                # partition in nums2

            left1 = nums1[i - 1] if i > 0 else float("-inf")
            right1 = nums1[i] if i < m else float("inf")
            left2 = nums2[j - 1] if j > 0 else float("-inf")
            right2 = nums2[j] if j < n else float("inf")

            # Correct partition found
            if left1 <= right2 and left2 <= right1:
                if (m + n) % 2 == 1:
                    return float(max(left1, left2))
                return (max(left1, left2) + min(right1, right2)) / 2.0

            # Move partition left/right
            if left1 > right2:
                hi = i - 1
            else:
                lo = i + 1

        raise ValueError("Input arrays must be sorted.")


class StreamingMedian:
    """
    Maintain median of a number stream using two heaps:
      - lower: max-heap for the lower half (implemented via negative values)
      - upper: min-heap for the upper half

    add(num): O(log n)
    median(): O(1)
    """

    def __init__(self) -> None:
        self.lower: List[int] = []  # max-heap via negatives
        self.upper: List[int] = []  # min-heap

    def add(self, num: int) -> None:
        """Add a number to the stream in O(log n)."""
        # Put into the appropriate heap
        if not self.lower or num <= -self.lower[0]:
            heapq.heappush(self.lower, -num)
        else:
            heapq.heappush(self.upper, num)

        # Rebalance so sizes differ by at most 1
        if len(self.lower) > len(self.upper) + 1:
            heapq.heappush(self.upper, -heapq.heappop(self.lower))
        elif len(self.upper) > len(self.lower) + 1:
            heapq.heappush(self.lower, -heapq.heappop(self.upper))

    def median(self) -> float:
        """Return the current median in O(1)."""
        total = len(self.lower) + len(self.upper)
        if total == 0:
            raise ValueError("No numbers have been added yet.")

        if len(self.lower) > len(self.upper):
            return float(-self.lower[0])
        if len(self.upper) > len(self.lower):
            return float(self.upper[0])

        return (-self.lower[0] + self.upper[0]) / 2.0
```

### Notes
- **Part 1** uses the standard binary-partition method, achieving **O(log(min(m, n)))** time.
- **Part 2** uses two heaps to keep the stream balanced:
  - `lower` stores the smaller half
  - `upper` stores the larger half
  - median is always available in **O(1)**

